# Created by OpenAI
"""o_proj of a block-fp8 MLA (GLM-5.3 FP8, TP8: 2048 -> 6144) in decode, verify and draft on gfx950:
fp8 activations at 1 x 128 scales times aiter's 16 x 16 shuffled fp8 weight at 128 x 128 scales,
bf16 out. One wave owns 32 output columns of a block of rows and runs the whole K in scaled
MFMAs. The rows are split into blocks of a tuned size; when they do not fill the last block, its
missing rows read as 0 and are not stored."""

from typing import NamedTuple
from triton.experimental import gluon
from triton.experimental.gluon import language as gl

class _DecodeTuning(NamedTuple):
    pack: int
    batch: int
    operand_width: int
    partitions: int
    tie_width: int
    tie_mask: int
    early_weights: int
    weight_first: int
    address_style: int = 0
    clobber_mask: int = 0
_DECODE_TUNING = {1: _DecodeTuning(4, 1, 32, 2, 2, 65535, 0, 5, address_style=2), 2: _DecodeTuning(4, 1, 16, 4, 4, 65356, 0, 7, address_style=8), 4: _DecodeTuning(4, 1, 16, 2, 4, 65356, 0, 7, address_style=8), 8: _DecodeTuning(2, 4, 16, 4, 1, 65535, 0, 0, address_style=8), 16: _DecodeTuning(1, 1, 16, 2, 4, 65450, 3, 0, clobber_mask=49152)}

@gluon.jit
def _select_last(values, INDEX: gl.constexpr):
    SHAPE: gl.constexpr = values.type.shape
    SIZE: gl.constexpr = SHAPE[-1]
    if SIZE == 1:
        return values.reshape(SHAPE[:-1])
    else:
        even, odd = gl.split(values.reshape(SHAPE[:-1] + [SIZE // 2, 2]))
        if INDEX % 2 == 0:
            return _select_last(even, INDEX // 2)
        else:
            return _select_last(odd, INDEX // 2)

@gluon.jit
def _register_tie(acc, WIDTH: gl.constexpr, CLOBBER: gl.constexpr):
    if WIDTH == 1:
        CONSTRAINT: gl.constexpr = '=v,0'
    elif WIDTH == 2:
        CONSTRAINT: gl.constexpr = '=v,=v,0,1'
    else:
        CONSTRAINT: gl.constexpr = '=v,=v,=v,=v,0,1,2,3'
    return gl.inline_asm_elementwise('', CONSTRAINT + (',~{memory}' if CLOBBER else ''), [acc], gl.float32, False, WIDTH)

@gluon.jit
def _rows_load(ptr, rows, live, MASKED: gl.constexpr):
    if MASKED:
        return gl.load(ptr, mask=rows < live, other=0.0)
    return gl.load(ptr)


@gluon.jit
def _rows_buffer_load(ptr, offsets, rows, live, MASKED: gl.constexpr):
    if MASKED:
        return gl.amd.cdna4.buffer_load(ptr, offsets, rows < live, 0.0)
    return gl.amd.cdna4.buffer_load(ptr, offsets)


@gluon.jit
def _rows_buffer_store(value, ptr, offsets, rows, live, MASKED: gl.constexpr):
    if MASKED:
        gl.amd.cdna4.buffer_store(value, ptr, offsets, rows < live)
    else:
        gl.amd.cdna4.buffer_store(value, ptr, offsets)

@gluon.jit
def _packed_weight_offsets(n, k, K: gl.constexpr, LINEAR_K: gl.constexpr=False, STYLE: gl.constexpr=0):
    if STYLE == 2:
        return n // 16 * (K * 16) + (k // 16 * 16 + n % 16) * 16 + k % 16
    elif STYLE == 6:
        return n // 16 * (K * 16) + k // 32 * 512 + (k // 16 % 2 * 16 + n % 16) * 16 + k % 16
    elif STYLE == 8:
        return n // 16 * (K * 16) + (k // 32 * 32 + k // 16 % 2 * 16 + n % 16) * 16 + k % 16
    elif LINEAR_K:
        return n // 16 * (K * 16) + k // 16 * 256 + n % 16 * 16 + k % 16
    else:
        return n // 16 * (K * 16) + k // 32 * 512 + k // 16 % 2 * 256 + n % 16 * 16 + k % 16

@gluon.jit
def _operand_offsets(M: gl.constexpr, BN: gl.constexpr, K: gl.constexpr, XM: gl.constexpr, XK: gl.constexpr, PACK: gl.constexpr, BATCH: gl.constexpr, KW: gl.constexpr, MMA: gl.constexpr, STYLE: gl.constexpr=0):
    if BATCH == 1:
        al: gl.constexpr = gl.DotOperandLayout(0, MMA, KW)
        bl: gl.constexpr = gl.DotOperandLayout(1, MMA, KW)
        ar = gl.arange(0, M * PACK, gl.SliceLayout(1, al))
        ak = gl.arange(0, 128, gl.SliceLayout(0, al))
        bk = gl.arange(0, 128, gl.SliceLayout(1, bl))
        bc = gl.arange(0, BN * PACK, gl.SliceLayout(0, bl))
        if PACK > 1:
            ao = ar[:, None] // PACK * XM + (ar[:, None] % PACK * 128 + ak[None, :]) * XK
            rows = ar[:, None] // PACK + 0 * ak[None, :]
            bo = _packed_weight_offsets(bc[None, :] % BN, bc[None, :] // BN * 128 + bk[:, None], K, M >= 2, STYLE)
        else:
            ao = ar[:, None] * XM + ak[None, :] * XK
            rows = ar[:, None] + 0 * ak[None, :]
            bo = _packed_weight_offsets(bc[None, :], bk[:, None], K, True, STYLE)
    else:
        mma3: gl.constexpr = gl.amd.AMDMFMALayout(4, [16, 16, 128], False, [1, 1, 1])
        al3: gl.constexpr = gl.DotOperandLayout(0, mma3, KW)
        bl3: gl.constexpr = gl.DotOperandLayout(1, mma3, KW)
        ai = gl.arange(0, BATCH, gl.SliceLayout(1, gl.SliceLayout(2, al3)))[:, None, None]
        ar = gl.arange(0, M * PACK, gl.SliceLayout(0, gl.SliceLayout(2, al3)))[None, :, None]
        ak = gl.arange(0, 128, gl.SliceLayout(0, gl.SliceLayout(1, al3)))[None, None, :]
        bi = gl.arange(0, BATCH, gl.SliceLayout(1, gl.SliceLayout(2, bl3)))[:, None, None]
        bk = gl.arange(0, 128, gl.SliceLayout(0, gl.SliceLayout(2, bl3)))[None, :, None]
        bc = gl.arange(0, BN * PACK, gl.SliceLayout(0, gl.SliceLayout(1, bl3)))[None, None, :]
        ao = ar // PACK * XM + (ar % PACK * 128 + ak + ai * PACK * 128) * XK
        rows = ar // PACK + 0 * (ak + ai)
        bo = _packed_weight_offsets(bc % BN, bc // BN * 128 + bk + bi * PACK * 128, K, True, STYLE)
    return (ao, bo, rows)

@gluon.jit
def _group_scales(XS, WS, sm, table, weight_scales, sn, XSM: gl.constexpr, XSK: gl.constexpr, WSN: gl.constexpr, WSK: gl.constexpr, M: gl.constexpr, OUT: gl.constexpr, GROUP: gl.constexpr, live, MASKED: gl.constexpr):
    if M == 1:
        sx = gl.convert_layout(_select_last(table, GROUP), gl.SliceLayout(1, OUT))
        sw = 1.0
    elif M <= 4:
        sx = _rows_load(XS + sm * XSM + GROUP * XSK, sm, live, MASKED)
        sw = gl.load(WS + sn // 128 * WSN + GROUP * WSK)
    else:
        sx = gl.convert_layout(_select_last(table, GROUP), gl.SliceLayout(1, OUT))
        sw = weight_scales[GROUP]
    return (sx, sw)

@gluon.jit
def _consume(groups, M: gl.constexpr, BN: gl.constexpr, PACK: gl.constexpr, MMA: gl.constexpr, OUT: gl.constexpr, TIE: gl.constexpr, CLOBBER: gl.constexpr, TIE_MASK: gl.constexpr, CLOBBER_MASK: gl.constexpr=0):
    zero = gl.zeros((M * PACK, BN * PACK), gl.float32, MMA)
    acc = gl.zeros((M, BN), gl.float32, OUT)
    for block in gl.static_range(len(groups)):
        a, b, scales = groups[block]
        product = gl.amd.cdna4.mfma_scaled(a, None, 'e4m3', b, None, 'e4m3', zero)
        if PACK > 1:
            fields = product.reshape((M, PACK, PACK, BN)).permute((0, 3, 1, 2))
        for p in gl.static_range(PACK):
            if PACK > 1:
                partial = gl.convert_layout(_select_last(_select_last(fields, p), p), OUT)
            else:
                partial = product
            sx, sw = scales[p]
            acc = gl.fma(partial, sx[:, None] * sw, acc)
            if TIE_MASK & 1 << block * PACK + p:
                acc = _register_tie(acc, TIE, CLOBBER or (M == 8 and block * PACK + p >= 12) or CLOBBER_MASK & 1 << block * PACK + p != 0)
    return acc

@gluon.jit
def _gemm_decode(X, XS, W, WS, Y, ROWS, N: gl.constexpr, K: gl.constexpr, XM: gl.constexpr, XK: gl.constexpr, XSM: gl.constexpr, XSK: gl.constexpr, WSN: gl.constexpr, WSK: gl.constexpr, M: gl.constexpr, CFG: gl.constexpr, MASKED: gl.constexpr):
    BN: gl.constexpr = 32
    PACK: gl.constexpr = CFG.pack
    BATCH: gl.constexpr = CFG.batch
    KW: gl.constexpr = CFG.operand_width
    TIE: gl.constexpr = CFG.tie_width
    TIE_MASK: gl.constexpr = CFG.tie_mask
    EARLY_W: gl.constexpr = CFG.early_weights
    WEIGHT_FIRST: gl.constexpr = CFG.weight_first
    PRELOAD_WS: gl.constexpr = M >= 8
    GROUPS: gl.constexpr = K // 128
    mma: gl.constexpr = gl.amd.AMDMFMALayout(4, [16, 16, 128], M == 16, [1, 1])
    al: gl.constexpr = gl.DotOperandLayout(0, mma, KW)
    bl: gl.constexpr = gl.DotOperandLayout(1, mma, KW)
    if M == 8:
        ol: gl.constexpr = gl.BlockedLayout([2, 1], [4, 16], [1, 1], [1, 0])
    elif PACK > 1:
        ol: gl.constexpr = gl.BlockedLayout([1, 1], [4, 16], [1, 1], [1, 0])
    else:
        ol: gl.constexpr = mma
    om = gl.arange(0, M, gl.SliceLayout(1, ol))
    on = gl.arange(0, BN, gl.SliceLayout(0, ol))
    first = gl.program_id(2) * M
    X = X + first * XM
    XS = XS + first * XSM
    Y = Y + first * N
    live = ROWS - first
    pid = gl.program_id(0).to(gl.uint32)
    pid = pid * (N // BN // CFG.partitions) + gl.program_id(1).to(gl.uint32)
    sn = pid * BN
    if BATCH == 1:
        ao, bo, rows = _operand_offsets(M, BN, K, XM, XK, PACK, BATCH, KW, mma, CFG.address_style)
    early_b = ()
    for e in gl.static_range(EARLY_W):
        early_b += (gl.amd.cdna4.buffer_load(W, bo + sn * K + e * PACK * 2048),)
    sw_tuple = ()
    scale_table = ()
    if PRELOAD_WS:
        for g in gl.static_range(GROUPS):
            sw_tuple += (gl.load(WS + sn // 128 * WSN + g * WSK),)
    if M <= 4:
        sm = gl.arange(0, M, gl.SliceLayout(1, ol))
    else:
        if M == 8:
            sl: gl.constexpr = gl.BlockedLayout([1, GROUPS], [4, 16], [1, 1], [1, 0])
        else:
            sl: gl.constexpr = gl.BlockedLayout([1, GROUPS], [16, 4], [1, 1], [0, 1])
        sm = gl.arange(0, M, gl.SliceLayout(1, sl))
        sg = gl.arange(0, GROUPS, gl.SliceLayout(0, sl))
        scale_table = _rows_load(XS + sm[:, None] * XSM + sg[None, :] * XSK, sm[:, None] + 0 * sg[None, :], live, MASKED)
    if BATCH > 1:
        ao, bo, rows = _operand_offsets(M, BN, K, XM, XK, PACK, BATCH, KW, mma, CFG.address_style)
    if M == 1:
        msl: gl.constexpr = gl.BlockedLayout([1, GROUPS], [4, 16], [1, 1], [1, 0])
        ms = gl.arange(0, 1, gl.SliceLayout(1, msl))
        gs = gl.arange(0, GROUPS, gl.SliceLayout(0, msl))
    groups = ()
    for block in gl.static_range(GROUPS // PACK // BATCH):
        base_g = block * PACK * BATCH
        if M <= 4:
            if WEIGHT_FIRST & 1 << block:
                b = gl.amd.cdna4.buffer_load(W, bo + sn * K + base_g * 2048)
                a = _rows_load(X + ao + base_g * 128 * XK, rows, live, MASKED)
            else:
                a = _rows_load(X + ao + base_g * 128 * XK, rows, live, MASKED)
                b = gl.amd.cdna4.buffer_load(W, bo + sn * K + base_g * 2048)
        elif M == 8:
            a = _rows_load(X + ao + base_g * 128 * XK, rows, live, MASKED)
            b = gl.amd.cdna4.buffer_load(W + base_g * 2048, bo + sn * K)
        else:
            a = _rows_buffer_load(X, ao + base_g * 128 * XK, rows, live, MASKED)
            if block < EARLY_W:
                b = early_b[block]
            else:
                b = gl.amd.cdna4.buffer_load(W, bo + sn * K + base_g * 2048)
        if M == 1 and block == 0:
            scale_table = gl.load(XS + ms[:, None] * XSM + gs[None, :] * XSK) * gl.load(WS + sn // 128 * WSN + gs[None, :] * WSK)
        if BATCH > 1:
            av = a.permute((1, 2, 0))
            bv = b.permute((1, 2, 0))
        for i in gl.static_range(BATCH):
            if BATCH > 1:
                aa = gl.convert_layout(_select_last(av, i), al)
                bb = gl.convert_layout(_select_last(bv, i), bl)
            else:
                aa, bb = (a, b)
            scales_tuple = ()
            for p in gl.static_range(PACK):
                sx, sw = _group_scales(XS, WS, sm, scale_table, sw_tuple, sn, XSM, XSK, WSN, WSK, M, ol, block * PACK * BATCH + i * PACK + p, live, MASKED)
                scales_tuple += ((sx, sw),)
            groups += ((aa, bb, scales_tuple),)
    acc = _consume(groups, M, BN, PACK, mma, ol, TIE, M == 2, TIE_MASK, CFG.clobber_mask)
    if M == 16:
        yl: gl.constexpr = gl.BlockedLayout([1, 8], [16, 4], [1, 1], [0, 1])
        value = gl.convert_layout(acc.to(gl.bfloat16), yl)
        ym = gl.arange(0, M, gl.SliceLayout(1, yl))
        yn = gl.arange(0, BN, gl.SliceLayout(0, yl))
        _rows_buffer_store(value, Y + sn, ym[:, None] * N + yn[None, :], ym[:, None] + 0 * yn[None, :], live, MASKED)
    else:
        _rows_buffer_store(acc.to(gl.bfloat16), Y + sn, om[:, None] * N + on[None, :], om[:, None] + 0 * on[None, :], live, MASKED)


# rows per block where not the default below (the tuning of that block size is used)
_BLOCK_ROWS = {1: 1, 2: 2, 3: 4, 4: 4, 5: 8, 6: 8, 7: 8, 8: 8}


def _block_rows(m):
    if m in _BLOCK_ROWS:
        return _BLOCK_ROWS[m]
    return 16 if m % 16 == 0 or m > 32 else 8


def run(*, a, b, a_scale, b_scale, scale_major_mode, trans_b, operand_format, bias, out_dtype, out):
    """out = (a * a_scale) @ (b * b_scale).T in bf16; a_scale holds its (m, k / 128) values column
    by column, as aiter's preshuffled GEMM reads them."""
    m, k = a.shape
    n = b.shape[0]
    assert (n, k) == (6144, 2048) and a.stride() == (k, 1) and b_scale.stride() == (k // 128, 1)
    rows = _block_rows(m)
    cfg = _DECODE_TUNING[rows]
    grid = (cfg.partitions, n // (32 * cfg.partitions), -(-m // rows))
    strides = (k, 1, 1, m, k // 128, 1)
    _gemm_decode[grid](a, a_scale, b, b_scale, out, m, n, k, *strides, rows, cfg, m % rows != 0, num_warps=1, num_stages=1)
